content.text:
The evidence points to one root cause: the connection from ts-seat-service to ts-order-service. Its slow calls never reach order-service, while seat's calls to order-other-service stay fast. The failure then spreads up the chain through travel, route-plan, and travel-plan to the user-facing dashboard.

```json
{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "network_loss",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT src, service_name, span_name, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM (SELECT 'a' src, * FROM abnormal_traces UNION ALL SELECT 'n', * FROM normal_traces) WHERE service_name IN ('ts-order-service','ts-order-other-service') AND span_name IN ('POST /api/v1/orderservice/order/tickets','POST /api/v1/orderOtherService/orderOther/tickets') AND attr_span_kind='Server' GROUP BY 1,2,3 ORDER BY 2,3,1",
          "claim": "Order-service ticket endpoint has no server spans in abnormal period (586 normal), while order-other-service ticket calls continue"
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms, round(quantile_cont(duration,0.95)/1e6,1) p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces WHERE service_name='ts-seat-service' AND attr_span_kind='Client' AND span_name='POST' GROUP BY 1",
          "claim": "Seat's outgoing POST calls: median 6 ms but p95 about 130 s, with 6 errors, the slow ones having no child span"
        },
        {
          "kind": "metric",
          "sql": "SELECT src, metric, attr_source, attr_destination, round(sum(value),1) total FROM (SELECT 'a' src, * FROM abnormal_metrics_sum UNION ALL SELECT 'n', * FROM normal_metrics_sum) WHERE metric='hubble_flows_processed_total' AND ((attr_source LIKE '%ts-seat-service%' AND attr_destination LIKE '%ts-order-service%') OR (attr_source LIKE '%ts-order-service%' AND attr_destination LIKE '%ts-seat-service%')) GROUP BY ALL ORDER BY 3,4,1",
          "claim": "Seat and order-service exchange many more flows per pair in abnormal, consistent with retransmitted/unanswered connection attempts on that pair"
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-seat-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT s.service_name caller, c.span_name, round(c.duration/1e6,1) c_ms, c.attr_status_code, s.service_name callee, round(s.duration/1e6,1) s_ms, s.attr_http_response_status_code code FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-service' AND c.attr_span_kind='Client' AND s.service_name='ts-seat-service' AND c.duration>1e9",
          "claim": "Travel-service calls to seat left_tickets take about 130 s and return HTTP 500 in abnormal period"
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, round(s.duration/1e6,1) s_ms, s.attr_http_response_status_code code FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-route-plan-service' AND s.service_name='ts-travel-service' AND s.duration>1e9",
          "claim": "Route-plan calls to travel-service trip_detail take 64 to 131 s in abnormal period"
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, s.service_name callee, s.span_name, round(s.duration/1e6,1) s_ms, s.attr_http_response_status_code code FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id AND s.trace_id=c.trace_id WHERE c.service_name='ts-travel-plan-service' AND s.service_name='ts-route-plan-service' AND s.duration>1e9",
          "claim": "Travel-plan calls to route-plan quickestRoute and minStopStations take about 130 s and return HTTP 500"
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%travelPlan%' GROUP BY 1,2,3",
          "claim": "Dashboard travelPlan requests (minStation, quickest) take about 20 s, matching client timeouts, in abnormal period"
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind kind, count(*) n, round(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%trips/left%' GROUP BY 1,2,3",
          "claim": "Dashboard trips/left requests slow to about 20 s p95 in abnormal period, while travel2 path stays fast"
        }
      ]
    }
  ]
}
```

